// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testFuzz_property(address from, address to, uint256 amount) public {
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        vm.assume(from != to);
        vm.assume(amount > 0 && amount < type(uint256).max);

        address[] memory tos = new address[](1);
        tos[0] = to;
        uint256[] memory amounts = new uint256[](1);
        amounts[0] = amount;

        SuccessToken token = new SuccessToken();
        vm.prank(from);
        token.approve(address(c), type(uint256).max);

        address privileged = address(uint160(uint256(keccak256(abi.encode(from, to, amount)))));
        vm.assume(privileged != from);
        vm.assume(privileged != address(0));

        vm.prank(privileged);
        bool result = c.transfer(from, address(token), tos, amounts);

        assertTrue(result);
    }
}

contract SuccessToken {
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        require(from != address(0), "invalid from");
        require(to != address(0), "invalid to");
        require(value > 0, "invalid value");
        require(allowance[from][msg.sender] >= value, "insufficient allowance");
        allowance[from][msg.sender] -= value;
        return true;
    }
}
